  'AC3: a resumed 206 without Content-Range totals received + remainder',
  () async {
    final body = filler(chunk * 3);
    var requests = 0;
    final client = streamingClient((request) {
      requests++;
      if (requests == 1) {
        return http.StreamedResponse(
          resetsAfter([body.sublist(0, chunk)]),
          200,
