/// Same shape as resetsAfter but with a print per phase.
Stream<List<int>> genBody(int n) async* {
  stdout.writeln('gen[$n]: start');
  yield List<int>.generate(409600, (i) => i & 0xFF);
  stdout.writeln('gen[$n]: yielded, about to throw');
  throw http.ClientException('connection closed while receiving');
}

